                rhs = parse_factor()
                q = abs(val) // abs(rhs)
                if (val < 0) != (rhs < 0):
                    q = -q
                val = q
            else:
                break
        return val

    def parse_factor():
        nonlocal pos
        typ, _ = peek()
        if typ == '-':
            consume()
            return -parse_factor()
        if typ == '+':
            consume()
            return parse_factor()
        return parse_primary()

    def parse_primary():
        nonlocal pos
        typ, val = peek()
        if typ == 'NUM':
            consume()
            return val
        if typ == '(':
            consume()
            v = parse_expr()
            typ2, _ = peek()
            if typ2 != ')':
                raise ValueError("Expected closing parenthesis")
            consume()
            return v
        raise ValueError(f"Unexpected token: {typ}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

